USE stroppy;
CREATE TABLE live_cluster_probe (id INT PRIMARY KEY, writes BIGINT NOT NULL);
DELIMITER //
CREATE PROCEDURE live_assert_cluster()
BEGIN
  IF NOT COALESCE(((SELECT VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME='WSREP_CLUSTER_SIZE')='3' AND (SELECT VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME='WSREP_LOCAL_STATE')='4' AND (SELECT VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME='WSREP_READY')='ON' AND (SELECT VARIABLE_VALUE FROM information_schema.GLOBAL_STATUS WHERE VARIABLE_NAME='WSREP_CLUSTER_STATUS')='Primary'), 0) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='live acceptance: expected three healthy cluster members';
  END IF;
  INSERT INTO live_cluster_probe VALUES (1,1) ON DUPLICATE KEY UPDATE writes=writes+1;
END//
DELIMITER ;

